import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import type { Claim } from './claims';
import { AMOUNT, claimsKey } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useClaimError } from './claimError';
import { useVoidReasons } from '../voidreasons/voidReasons';

type Action = 'open' | 'review' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle' | 'delete' | 'restore';

/** The kinds a proof can be, as the server takes them. */
const PROOF_KINDS = ['receipt', 'photo'];

const ACTIONS: Array<{ action: Action; label: string }> = [
  { action: 'open', label: 'Open' },
  { action: 'review', label: 'Review' },
  { action: 'settle', label: 'Settle' },
  { action: 'approve', label: 'Approve' },
  { action: 'reject', label: 'Reject' },
  { action: 'void', label: 'Void' },
  { action: 'resettle', label: 'Re-settle' },
  { action: 'delete', label: 'Delete' },
  { action: 'restore', label: 'Restore' },
];

const REFUSED: Partial<Record<Action, string>> = {
  open: ' (your role may not be allowed to open a claim)',
  review: ' (only a steward reviews a claim in REVIEW, which opens it)',
  settle: ' (a date to settle as of must be on or before today, when the claim existed; the user who opened it cannot settle it, one whose due is above the proof threshold needs a proof, of each proof kind set, and your role may not be allowed to settle)',
  void: ' (your role may not be allowed to void a claim; only a steward voids a settled claim, within 7 days of its settlement; while the sheet has void reasons, choose one)',
  approve: ' (only a steward approves a pending claim, and not the user who opened it; one whose due is above the proof threshold needs a proof, of each proof kind set)',
  reject: ' (only a steward rejects a pending claim, and a reason is required)',
  resettle: ' (only a steward re-settles a settled claim)',
  delete: ' (only a DRAFT claim not due in a closed period is deleted)',
  restore: ' (a deleted claim is restored only on the day it was deleted)',
};

// A claim's status and the buttons that change it. Every button is shown; the server refuses a
// change the status does not allow, and the refusal shows as the claim's error. A clerk's settle
// above the clerk limit makes the claim PENDING; a settle sends the as-of date typed beside it (blank: now), fixing
// the due as it stood at the end of that day; a reject sends the reason typed beside it. A role
// allowed to reassign (standing rule: a steward) moves a DRAFT, OPEN or PENDING claim to the person chosen beside the
// Move button. A steward re-settles a SETTLED claim, freezing it again at today's figure. An OPEN claim is deferred to the
// date typed beside the Defer button. The Add proof button raises the claim's proofs count by one, of the kind chosen
// beside it (none chosen: a receipt; not on a SETTLED or VOID claim, nor one due by a date in a closed period). The Split button splits the amount typed beside it off an
// OPEN claim into a new OPEN claim of the same person (more than 0.00 and less than the claim's amount); Part-settle splits its
// amount off the same way and settles the new claim at once (PENDING above the clerk limit), refused whole when either
// would be (the settle judged on the original claim). A steward
// re-dates an OPEN or PENDING claim to the date typed beside the Re-date button. While the sheet has void reasons, a void
// sends the reason chosen beside it (none chosen: the server refuses it). Delete sets a DRAFT claim aside as DELETED;
// Restore makes it a DRAFT again, only on the sheet's today it was deleted. An open whose due is above the review threshold
// makes the claim REVIEW; a steward's Review then opens it.
export function ClaimStatus({ claim }: { claim: Claim }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [error, setError] = useClaimError(claim.id);
  const [reason, setReason] = useState('');
  const [settleOn, setSettleOn] = useState('');
  const [voidReason, setVoidReason] = useState('');
  const voidReasons = useVoidReasons().data ?? [];
  const [moveTo, setMoveTo] = useState('');
  const [deferTo, setDeferTo] = useState('');
  const [proofKind, setProofKind] = useState('');
  const [splitAmount, setSplitAmount] = useState('');
  const [settlePartAmount, setSettlePartAmount] = useState('');
  const [redateTo, setRedateTo] = useState('');
  const others = (usePeople().data ?? []).filter((p) => p.id !== claim.personId);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const change = useMutation({
    mutationFn: (action: Action) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/${action}?user=${encodeURIComponent(user)}`,
        action === 'reject'
          ? { reason }
          : action === 'void'
            ? { reason: voidReason }
            : action === 'settle'
              ? { on: settleOn.trim() }
              : {},
      ),
    onSuccess: async (_c, action) => {
      if (action === 'reject') setReason('');
      if (action === 'void') setVoidReason('');
      if (action === 'settle') setSettleOn('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: (_e, action) => setError(`This ${claim.status} claim cannot be changed by ${action}${REFUSED[action] ?? ''}.`),
  });

  const reassign = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/person?user=${encodeURIComponent(user)}`, {
        personId,
      }),
    onSuccess: async () => {
      setMoveTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be moved (only a DRAFT, OPEN or PENDING claim is moved, by a role allowed to reassign).`),
  });

  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/deferral?user=${encodeURIComponent(user)}`, {
        until,
      }),
    onSuccess: async () => {
      setDeferTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be deferred to that date (only an OPEN claim, to a date after today, outside a closed period).`),
  });

  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/split?user=${encodeURIComponent(user)}`, {
        amount,
      }),
    onSuccess: async () => {
      setSplitAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be split by that amount (only an OPEN claim, not deferred nor in a closed period, by more than 0.00 and less than its amount, by a role allowed to open a claim).`,
      ),
  });

  const settlePart = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/settle/part?user=${encodeURIComponent(user)}`,
        { amount },
      ),
    onSuccess: async () => {
      setSettlePartAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be part-settled by that amount (it must be split as Split does and settled as Settle does: not by the user who opened or last edited it, and one whose due is above the proof threshold needs a proof).`,
      ),
  });

  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/date?user=${encodeURIComponent(user)}`, {
        date,
      }),
    onSuccess: async () => {
      setRedateTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be re-dated to that date (only a steward re-dates an OPEN or PENDING claim, not after its person's retirement, nor one due by a date in a closed period).`,
      ),
  });

  const proof = useMutation({
    mutationFn: (kind: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/proofs?user=${encodeURIComponent(user)}`, {
        kind,
      }),
    onSuccess: async () => {
      setProofKind('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be given a proof (not a SETTLED or VOID claim, nor one in a closed period).`),
  });

  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, label }) => (
        <span key={action}>
          <button
            type="button"
            data-testid={`claim-${action}`}
            disabled={change.isPending}
            onClick={() => {
              setError('');
              once(() => change.mutateAsync(action));
            }}
          >
            {label}
          </button>
          {action === 'settle' && (
            <input
              data-testid="claim-settle-date"
              aria-label="Settle as of"
              placeholder="as of yyyy-mm-dd"
              value={settleOn}
              onChange={(e) => {
                setSettleOn(e.target.value);
                setError('');
              }}
            />
          )}
        </span>
      ))}
      <input
        data-testid="claim-reject-reason"
        aria-label="Reject reason"
        placeholder="reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          setError('');
        }}
      />
      {voidReasons.length > 0 && (
        <select
          data-testid="claim-void-reason"
          aria-label="Void reason"
          value={voidReason}
          onChange={(e) => {
            setVoidReason(e.target.value);
            setError('');
          }}
        >
          <option value="">void reason…</option>
          {voidReasons.map((r) => (
            <option key={r} value={r}>
              {r}
            </option>
          ))}
        </select>
      )}
      <select
        data-testid="claim-reassign-to"
        aria-label="Move to"
        value={moveTo}
        onChange={(e) => {
          setMoveTo(e.target.value);
          setError('');
        }}
      >
        <option value="">move to…</option>
        {others.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={reassign.isPending}
        onClick={() => {
          setError('');
          if (!moveTo) {
