        value={splitAmount}
        onChange={(e) => {
          setSplitAmount(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="claim-split"
        disabled={split.isPending}
        onClick={() => {
          setError('');
          const amount = splitAmount.trim();
          if (!AMOUNT.test(amount)) {
            setError('Type the amount to split off as 0.00.');
            return;
